#include <stdio.h>

typedef enum { READY, RUNNING, DONE } State;

typedef struct {
    int id;
    State state;
    void (*func)(void*);
    void *arg;
} Task;

void task1(void *arg) { printf("Task 1 running\n"); }
void task2(void *arg) { printf("Task 2 running\n"); }
void task3(void *arg) { printf("Task 3 running\n"); }

int main() {
    Task tasks[3] = {
        {1, READY, task1, NULL},
        {2, READY, task2, NULL},
        {3, READY, task3, NULL}
    };
    for (int i = 0; i < 3; i++) {
        printf("Running task %d\n", tasks[i].id);
        tasks[i].func(tasks[i].arg);
        tasks[i].state = DONE;
    }
    return 0;
}
